-- Auto-generated by scripts/curriculum/build-level-sql.mjs -- do not
-- hand-edit the lesson content below; regenerate from the source plan
-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := 'cd5763ec-82e4-46ae-a45e-00e32deeb6a9';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Product Photos and Listings That Sell', 'The existing lessons show you how to open a shop on four platforms. This one is about the thing that decides whether anyone buys: how the product looks and what the listing says.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Product Photography Without a Studio', 'Shopify''s own guide to shooting professional-looking product photos on a small budget — light, backdrop and setup you can put together at home. About 14 minutes.', 'https://www.youtube.com/watch?v=uZeRLXODK5w', 1,
      array['Light a product using a window instead of buying equipment', 'Build a clean, consistent backdrop from materials you already have', 'Explain why photo quality decides the sale before the price does'],
      'Online, your photograph IS the product. The buyer cannot pick it up, feel the fabric, or check the finish. Everything they decide comes from an image on a phone screen, usually in a few seconds while scrolling.

This is the single highest-return skill for a small seller, and it costs almost nothing. A good photo of an ordinary product outsells a bad photo of an excellent one, every time.

WHAT ACTUALLY MATTERS, in order:

LIGHT. Not a ring light — a window. Soft, indirect daylight is the best free lighting there is. Put the product beside a window, not in direct sun, and shoot with the light coming from the side or slightly behind you. Overhead room lights are the enemy: they cast hard yellow shadows and make white things look grubby.

BACKGROUND. Plain and consistent. A white sheet, a large piece of card, a clean wall. The point is that nothing competes with the product, and that all your listings look like they come from one shop rather than five different sellers.

STEADINESS. Prop the phone on a stack of books rather than holding it. Sharp beats expensive.

SHOW SCALE AND DETAIL. One clear photo of the whole thing, then close-ups of the parts a buyer would inspect in person — the stitching, the plug, the label. If size is hard to judge, put a familiar object beside it.

Be honest in your photos. A product that arrives looking different from its picture produces a refund, a bad review, and a customer who never returns — which costs far more than the sale was worth.',
      'Photograph one real product twice. First the way most people do: on a cluttered table under the ceiling light. Then properly: beside a window, on a plain background, phone propped steady, with one wide shot and two close-ups. Put the two side by side on your phone screen. That difference is what you are selling.',
      '[{"question":"What is the best free lighting for product photos?","options":["Soft, indirect daylight from a window","The overhead light in the room","Direct midday sun outdoors","Your phone''s flash"],"correct_index":0},{"question":"Why does a plain, consistent background matter beyond looking tidy?","options":["Nothing competes with the product, and all your listings look like one shop","It makes the image file smaller","Search engines require plain backgrounds","It removes the need for close-up shots"],"correct_index":0}]'::jsonb),
    (v_m1, 'Shooting Products With Just a Smartphone', 'Shopify''s practical walkthrough of photographing products at home using only a phone — settings, angles and the shots a listing needs. About 10 minutes.', 'https://www.youtube.com/watch?v=ZFqvFP4GsvI', 2,
      array['Use your phone''s own settings to get a sharper, truer photo', 'Capture the standard set of shots a product listing needs', 'Edit lightly without misrepresenting the product'],
      'A modern phone camera is genuinely good enough. The gap between a phone photo and a studio photo is almost entirely technique, not hardware.

PHONE SETTINGS WORTH KNOWING:

- Tap the screen on the product to set focus and exposure there, then slide to adjust brightness. Left to itself, the camera exposes for the whole frame and often makes a white product grey.
- Turn on gridlines and keep the product centred and level. Crooked photos read as careless.
- Avoid digital zoom — it just crops and softens. Move closer instead.
- Clean the lens. It sounds trivial; a smeared lens is the most common cause of soft, hazy product photos.
- Turn the flash off. It flattens the product and produces harsh reflections on anything shiny.

THE SHOT LIST for any product: one clean hero shot on a plain background, two or three detail shots, one showing scale, and — where it applies — one in use. That last one does more work than people expect: a bag being carried, a lamp switched on in a room. Buyers imagine themselves owning it.

EDITING. Crop, straighten, and adjust brightness and contrast a little. That is all. Never change the colour of the product itself. A buyer who ordered navy blue and receives black will ask for their money back, and they will be right.

CONSISTENCY beats perfection. Same background, same angle, same crop across every listing. A shop where every photo matches looks established even when it is two weeks old.',
      'Shoot the full standard set for one product: hero, two details, one for scale, one in use. Keep the phone in the same position and the background identical throughout. Then do it again for a second product, matching the first exactly. Put both listings side by side — the consistency is what makes a shop look real.',
      '[{"question":"Why tap the screen on the product before shooting?","options":["It sets focus and exposure for the product rather than the whole frame","It increases the photo''s resolution","It turns on the flash automatically","It removes the background"],"correct_index":0},{"question":"Which edit should you never make to a product photo?","options":["Changing the product''s actual colour","Cropping the image","Straightening a crooked shot","Slightly raising the brightness"],"correct_index":0}]'::jsonb),
    (v_m1, 'Writing a Product Description That Sells', 'Shopify on copywriting for product pages — what to say, what to leave out, and why most descriptions fail. About 14 minutes.', 'https://www.youtube.com/watch?v=f1Jkcc6J7mo', 3,
      array['Write about benefits rather than listing specifications', 'Answer the questions that stop a buyer from ordering', 'Structure a description for someone skimming on a phone'],
      'Most product descriptions are a specification sheet written by someone who already owns the product. They answer questions nobody asked and skip the ones stopping the sale.

FEATURES VERSUS BENEFITS. "5000mAh battery" is a feature. "Charges your phone twice before it needs power itself" is the same fact translated into the buyer''s life. State the feature, then say what it means for them. Every specification should earn its place by answering "so what?"

ANSWER THE OBJECTIONS. Write down the three things that would make YOU hesitate — will it fit, is it genuine, what if it breaks, how long is delivery — and answer all three in the description. Every unanswered question is a reason to close the tab. This single habit does more than any clever wording.

WRITE FOR SKIMMING. Nobody reads a paragraph on a phone. Short opening line saying what it is and who it''s for. Then bullet points. Then details underneath for the small number who want them.

BE SPECIFIC. "High quality" means nothing — every seller writes it, including dishonest ones. "Double-stitched seams, 100% cotton, machine washable" is checkable, and checkable claims are what build trust.

A NOTE ON LOCAL SELLING, which the video does not cover: if you sell through WhatsApp or Instagram rather than a website, the description is the message you paste when someone asks about a product. Write it once, keep it saved, and make it complete — price, sizes, delivery time, how to pay. Retyping it every time is how details get missed and how you end up quoting two different prices to two customers.',
      'Take one product and write its description in three parts: one line saying what it is and who it''s for, four bullets translating features into benefits, then the answers to the three questions most likely to stop a buyer. Read it back and delete every phrase that could appear on any product in the world — "high quality", "best price", "amazing". What survives is your actual description.',
      '[{"question":"\"5000mAh battery\" is a feature. What is the benefit?","options":["It charges your phone twice before needing power itself","It has a large capacity rating","It is a premium component","It uses lithium-ion technology"],"correct_index":0},{"question":"Why answer likely objections directly in the description?","options":["Every unanswered question is a reason for the buyer to leave","Search engines rank longer descriptions higher","It is legally required","It lets you avoid publishing a returns policy"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Pricing, Margins and Getting It Delivered', 'The money side. Sellers who skip this can be busy, popular and losing money on every order without realising it.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'Pricing So You Actually Make Money', 'Shopify on how to arrive at a price — covering costs, understanding margin, and why undercutting everyone is a trap. About 8 minutes.', 'https://www.youtube.com/watch?v=xQWUm_eHjGk', 1,
      array['Work out the true total cost of selling one unit', 'Calculate your margin and know what it needs to cover', 'Explain why the cheapest price is usually the worst strategy'],
      'The most common mistake in small online selling is pricing at cost plus a bit, then discovering the bit was never enough.

COUNT EVERY COST, not just what you paid for the item:

- What the product cost you
- Transport to get it to you
- Packaging
- Delivery to the customer, if you absorb any of it
- Platform commission (Jumia and similar take a percentage — check the real rate)
- Payment charges (M-Pesa till and card fees are small per transaction but real)
- Your own time

That total is your true unit cost. Most beginners count only the first item on that list, which is why their profit vanishes.

MARGIN is what is left after all of it, and it is not pocket money. It has to cover the items that do not sell, returns and damage, the cost of finding the next customer, and eventually paying yourself. A margin that looks generous per unit is often barely adequate across a month.

WHY UNDERCUTTING IS A TRAP. Being the cheapest is the one advantage anyone can copy instantly, and the moment they do you have nothing left — you have already given away your only argument. Competing on price is a race you win by earning the least. Better differences: faster delivery, honest photos, answering messages quickly, taking returns without an argument. Those are hard to copy and they let you charge more.

A LOCAL NOTE beyond the video: if you sell pay-on-delivery, price in the reality that some deliveries are refused at the door. You still paid the rider. Refused deliveries are a real cost of doing business here and they belong in your margin, not in your surprises.',
      'Take one product and write out every line of its true cost — product, transport, packaging, delivery, platform commission, payment fees. Add them. Compare the total to what you currently charge. Work out what one refused pay-on-delivery order per twenty costs you, and check whether your margin absorbs it. Many sellers discover here that their best-selling item is their least profitable.',
      '[{"question":"You count only what you paid for the item. What are you most likely to miss?","options":["Packaging, delivery, platform commission and payment fees","The retail price of competitors","The colour options you offer","Your shop''s opening hours"],"correct_index":0},{"question":"Why is being the cheapest seller a weak strategy?","options":["Anyone can copy it instantly, and then you have no advantage left","Customers distrust low prices","Platforms ban low pricing","It makes photography harder"],"correct_index":0}]'::jsonb),
    (v_m2, 'Shipping and Fulfilment Without Losing the Customer', 'Shopify''s complete guide to shipping and fulfilment — packaging, rates, and what happens after the order comes in. About 11 minutes.', 'https://www.youtube.com/watch?v=088tKYu7kKY', 2,
      array['Decide how to charge for delivery rather than absorbing it by accident', 'Package an order so it arrives in the condition you photographed', 'Set delivery expectations you can actually meet'],
      'The sale is not finished when someone pays. It is finished when the product arrives intact and the buyer is satisfied — and almost every bad review a small seller gets comes from this stage, not the product.

HOW TO CHARGE FOR DELIVERY. Three honest options: charge the real cost, build it into the price and advertise free delivery, or offer free delivery above a threshold. All three work. What does not work is guessing, which is how sellers end up paying to fulfil their own orders.

FREE DELIVERY IS NOT FREE. It converts better because buyers hate a cost appearing at checkout, but it comes out of your margin. Build it into the price deliberately or not at all.

PACKAGING is the last thing you control and the first thing the customer touches. It has one job: the product arrives exactly as photographed. Wrap anything fragile properly. A broken item costs you the product, the delivery, the refund and the review — four losses from saving a few shillings on a bubble wrap sleeve.

SET EXPECTATIONS YOU CAN MEET. "Delivered in 2–3 days" that becomes five days makes an angry customer. "Delivered in 5 days" that arrives in three makes a delighted one. Same delivery. Under-promise deliberately.

COMMUNICATE WHEN IT MOVES. A message saying the order is on its way, ideally with a rider''s number or a tracking code, prevents most "where is my order?" anxiety before it starts. Silence after payment is what makes buyers assume they have been cheated.

AND WHEN IT GOES WRONG — a late, lost or damaged order — reply quickly and fix it without an argument. A problem handled well produces a more loyal customer than an order that went smoothly, because now they know what happens when something breaks.',
      'Work out the real delivery cost for one product to a nearby town and to a distant one, then decide which of the three charging approaches you will use and write it down as a policy. Then write the two messages you will send every buyer: one confirming the order with a realistic delivery window, one saying it is on its way. Saving those now means you send them every time instead of when you remember.',
      '[{"question":"Which delivery promise produces the happier customer?","options":["Promising 5 days and arriving in 3","Promising 2 days and arriving in 5","Making no promise at all","Promising same-day for every destination"],"correct_index":0},{"question":"What does ''free delivery'' actually mean for a seller?","options":["The cost comes out of your margin, so it must be built into the price deliberately","The platform covers the delivery cost","Delivery companies waive the fee for small sellers","It only applies to digital products"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
